const response = $input.first().json;
const previousData = $('Save Previous Version').first().json;

// Handle both Anthropic and OpenAI response formats
let content = response.message?.content || (Array.isArray(response.content) ? response.content[0].text : response.content) || response.text;

// Nettoyer le JSON si wrapped dans markdown
if (typeof content === 'string') {
  content = content.replace(/```json\n?/g, '').replace(/```\n?/g, '').trim();
  content = JSON.parse(content);
}

return {
  json: {
    post_id: previousData.post_id,
    hook: content.hook,
    corps: content.corps,
    cta: content.cta,
    hashtags: content.hashtags,
    modifications_effectuees: content.modifications_effectuees,
    version_precedente: previousData.version_precedente
  }
};

return {
  json: {
    success: true,
    post_id: $json.post_id,
    modifications: $json.modifications_effectuees
  }
};

return {
  json: {
    success: false,
    error: "La modification a échoué. Veuillez réessayer."
  }
};
